 /// persona tiene que cambiarla antes de usar el sistema.\n  debeCambiarContrasena Boolean @default(false) @map(\"debe_cambiar_contrasena\")\n\n  // --- Lo que pide better-auth (columnas nuevas, con valor por defecto) ---\n  /// No se verifican correos: el login es con usuario y contraseña.\n  emailVerified Boolean   @default(false) @map(\"email_verified\")\n  /// better-auth lo espera; las fotos viven en `fotos_perfil`.\n  image         String?\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @default(now()) @updatedAt @map(\"updated_at\")\n  sesiones      Session[]\n  cuentasAcceso Account[]\n\n  rol       Rol               @relation(fields: [roleId], references: [id])\n  proyectos UsuarioProyecto[]\n\n  proyectosDisenados     Proyecto[]             @relation(\"ProyectosDisenados\")\n  proyectosDesarrollados Proyecto[]             @relation(\"ProyectosDesarrollados\")\n  cambiosDeEtapa         HistorialEtapa[]\n  cambiosDePago          HistorialPago[]\n  recordatorios          RecordatorioProyecto[]\n  cotizaciones           CotizacionAdicional[]\n  pendientes             Pendiente[]\n  notificaciones         Notificacion[]\n  reunionesCreadas       Reunion[]              @relation(\"ReunionesCreadas\")\n  integracionGoogle      IntegracionGoogle?\n  fotoPerfil             FotoPerfil?\n  comunicadosCreados     Comunicado[]\n  comunicadosCerrados    ComunicadoCierre[]\n  reuniones              ReunionUsuario[]\n  notasEnviadas          NotaAdmin[]\n  respuestasNota         RespuestaNota[]\n  puestos                UsuarioPuesto[]\n\n  @@index([roleId])\n  @@map(\"users\")\n}\n\n/// En qué trabaja una persona, aparte de su rol (que es el de permisos). Una\n/// misma persona puede diseñar y desarrollar: aparece en los dos selectores y\n/// ve los dos tableros. Sin filas, se usan los puestos que implica su rol.\nmodel UsuarioPuesto {\n  usuarioId Int      @map(\"usuario_id\")\n  puesto    Puesto\n  createdAt DateTime @default